package com.sacco.mvp.clients.applications.repository;

import com.sacco.mvp.clients.applications.dto.ClientApplicationDtos.*;
import com.sacco.mvp.security.AppUserPrincipal;
import lombok.RequiredArgsConstructor;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Repository;
import java.time.OffsetDateTime;
import java.util.*;

@Repository @RequiredArgsConstructor
public class ClientApplicationRepository {
    private final JdbcTemplate jdbc;
    public Optional<Choice> officer(AppUserPrincipal a,UUID id){if(!officerExists(a,id))return Optional.empty();return jdbc.query("select id,full_name from members where id=? and sacco_id=? and station_id=?",(r,n)->new Choice(r.getObject(1,UUID.class),r.getString(2)),id,a.getSaccoId(),a.getStationId()).stream().findFirst();}
    public List<Choice> guarantors(AppUserPrincipal a,Collection<UUID> ids){if(ids.isEmpty())return List.of();if(ids.size()>20)throw new IllegalArgumentException("applications.error.guarantors");return new org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate(jdbc).query("select id,member_no||' - '||full_name from members where id in(:ids) and sacco_id=:institution and station_id=:branch and status='ACTIVE' and is_member=true",Map.of("ids",ids,"institution",a.getSaccoId(),"branch",a.getStationId()),(r,n)->new Choice(r.getObject(1,UUID.class),r.getString(2)));}
    public boolean officerExists(AppUserPrincipal a,UUID id){return Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from members where id=? and sacco_id=? and station_id=? and status='ACTIVE' and staff_access_status='ACTIVE' and (position='LOAN_OFFICER' or exists(select 1 from member_staff_roles r where r.member_id=members.id and r.role_name='LOAN_OFFICER')))",Boolean.class,id,a.getSaccoId(),a.getStationId()));}
    public void lock(String key){jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,key);}
    public Optional<Command> retry(AppUserPrincipal a,UUID key){return jdbc.query("select id,application_id,version,payload_hash from client_application_command where sacco_id=? and station_id=? and request_key=? and actor_id=?",(r,n)->new Command(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getInt(3),r.getString(4)),a.getSaccoId(),a.getStationId(),key,a.getMemberId()).stream().findFirst();}
    public void command(AppUserPrincipal a,UUID application,UUID client,int version,UUID key,String hash,String data,OffsetDateTime at){jdbc.update("insert into client_application_command values(?,?,?,?,?,?,?,?,?,?::jsonb,?)",UUID.randomUUID(),application,client,a.getSaccoId(),a.getStationId(),version,key,hash,a.getMemberId(),data,at);}
    public List<Choice> clients(AppUserPrincipal a,String search,int page){return jdbc.query("select id,member_no||' - '||full_name from members where sacco_id=? and station_id=? and is_member=true and status='ACTIVE' and strpos(lower(member_no||' '||full_name||' '||coalesce(phone,'')),?)>0 order by full_name,id limit 26 offset ?",(r,n)->new Choice(r.getObject(1,UUID.class),r.getString(2)),a.getSaccoId(),a.getStationId(),search.toLowerCase(Locale.ROOT),page*25);}
    public List<Choice> products(AppUserPrincipal a,String search,int page){return jdbc.query("select id,coalesce(nullif(product_name,''),loan_type) from loan_product_settings where sacco_id=? and active=true and coalesce(custom_recording_configuration,false)=false and coalesce(product_status,'ACTIVE')='ACTIVE' and strpos(lower(coalesce(product_name,loan_type)),?)>0 order by display_order,id limit 26 offset ?",(r,n)->new Choice(r.getObject(1,UUID.class),r.getString(2)),a.getSaccoId(),search.toLowerCase(Locale.ROOT),page*25);}
    public List<Choice> officers(AppUserPrincipal a,String search,int page){return jdbc.query("select id,full_name from members where sacco_id=? and station_id=? and status='ACTIVE' and staff_access_status='ACTIVE' and (position='LOAN_OFFICER' or exists(select 1 from member_staff_roles r where r.member_id=members.id and r.role_name='LOAN_OFFICER')) and strpos(lower(full_name),?)>0 order by full_name,id limit 26 offset ?",(r,n)->new Choice(r.getObject(1,UUID.class),r.getString(2)),a.getSaccoId(),a.getStationId(),search.toLowerCase(Locale.ROOT),page*25);}
    public List<Row> list(AppUserPrincipal a,UUID client,String search,int page){return jdbc.query("select l.id,l.applicant_member_id,l.application_number::text,m.full_name,coalesce(nullif(p.product_name,''),p.loan_type),l.status,l.amount,l.created_at from loan_applications l join members m on m.id=l.applicant_member_id left join loan_product_settings p on p.id=l.loan_product_setting_id where l.sacco_id=? and l.station_id=? and (?::uuid is null or l.applicant_member_id=?) and strpos(lower(l.application_number::text||' '||m.member_no||' '||m.full_name),?)>0 order by l.created_at desc,l.id limit 26 offset ?",(r,n)->new Row(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getBigDecimal(7),r.getObject(8,OffsetDateTime.class)),a.getSaccoId(),a.getStationId(),client,client,search.toLowerCase(Locale.ROOT),page*25);}
    public Details details(AppUserPrincipal a,UUID id,UUID client){return jdbc.query("select l.id,l.applicant_member_id,l.application_number::text,m.full_name,l.status,coalesce((select max(version) from client_application_command c where c.application_id=l.id),0),l.form_data::text,l.attachments_json::text,l.financial_snapshot::text from loan_applications l join members m on m.id=l.applicant_member_id where l.id=? and l.sacco_id=? and l.station_id=? and (?::uuid is null or l.applicant_member_id=?)",(r,n)->new Details(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getString(3),r.getString(4),r.getString(5),r.getInt(6),r.getString(7),r.getString(8),r.getString(9)),id,a.getSaccoId(),a.getStationId(),client,client).stream().findFirst().orElseThrow(()->new AccessDeniedException("Application unavailable"));}
    public Optional<String> latestForm(AppUserPrincipal a,UUID id,UUID client){details(a,id,client);return jdbc.query("select details::text from client_application_command where application_id=? and sacco_id=? and station_id=? order by version desc limit 1",(r,n)->r.getString(1),id,a.getSaccoId(),a.getStationId()).stream().findFirst();}
}
